class Solution {
    void count(Node* node, array<int, 26>& freq) {
        if (!node) return;
        if (!node->left && !node->right) {
            ++freq[node->val - 'a'];
            return;
        }
        count(node->left, freq);
        count(node->right, freq);
    }
public:
    bool checkEquivalence(Node* root1, Node* root2) {
        array<int, 26> a = {}, b = {};
        count(root1, a);
        count(root2, b);
        return a == b;
    }
};
